return items.map(item => {
  const data = item.json;

  let result;

  // 1. Formato antigo:
  // {
  //   "action": "parse",
  //   "text": "{\"output\": {...}}"
  // }
  if (typeof data.text === 'string') {
    try {
      const parsed = JSON.parse(data.text);

      if (parsed.output) {
        result = parsed.output;
      } else {
        result = parsed;
      }
    } catch (error) {
      // Continua para as outras possibilidades
    }
  }

  // 2. JSON já está diretamente no item
  if (!result && data.responseAI !== undefined) {
    result = data;
  }

  // 3. Tenta encontrar JSON dentro de algum campo de texto
  if (!result) {
    for (const [key, value] of Object.entries(data)) {
      if (typeof value !== 'string') continue;

      try {
        const parsed = JSON.parse(value);

        if (parsed.output) {
          result = parsed.output;
          break;
        }

        if (parsed.responseAI !== undefined) {
          result = parsed;
          break;
        }
      } catch {
        // Não é JSON, continua procurando
      }
    }
  }

  // Se não encontrou o formato esperado
  if (!result) {
    return {
      json: {
        error: 'Não foi possível encontrar a resposta do AI Agent.',
        input: data
      }
    };
  }

  return {
    json: {
      responseAI: result.responseAI ?? '',
      Order: result.Order ?? '',
      DeliveryType: result.DeliveryType ?? null,
      DeliveryAddress: result.DeliveryAddress ?? null,
      PaymentTiming: result.PaymentTiming ?? null,
      ConversationFinished: result.ConversationFinished ?? false,
      Total: result.Total ?? result.total ?? null
    }
  };
});
